// Pre-Hearing Evaluation & Payload Builder
// Supports both automated cron schedule and manual test inputs

const items = $input.all();
let manualTargetDate = null;
let manualCaseId = null;

try {
  if ($('Execute Workflow Trigger').isExecuted) {
    const minp = $('Execute Workflow Trigger').first().json;
    if (minp && minp.target_date) manualTargetDate = String(minp.target_date).trim();
    if (minp && minp.case_id) manualCaseId = String(minp.case_id).trim();
  }
} catch (e) {
  // Executed from Schedule trigger
}

const reminderDays = Number($vars.HEARING_REMINDER_LEAD_DAYS || 4);

function parseDate(str) {
  if (!str) return null;
  str = String(str).trim();
  const parts = str.includes('/') ? str.split('/') : (str.includes('-') ? str.split('-') : []);
  if (parts.length === 3) {
    if (parts[0].length === 4) {
      // YYYY-MM-DD
      const year = parseInt(parts[0], 10);
      const month = parseInt(parts[1], 10) - 1;
      const day = parseInt(parts[2], 10);
      return new Date(year, month, day);
    } else {
      // DD/MM/YYYY
      const day = parseInt(parts[0], 10);
      const month = parseInt(parts[1], 10) - 1;
      const year = parseInt(parts[2], 10);
      return new Date(year, month, day);
    }
  }
  const parsed = new Date(str);
  return isNaN(parsed.getTime()) ? null : parsed;
}

function diffDays(targetDate, baseDate) {
  const utcTarget = Date.UTC(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate());
  const utcBase = Date.UTC(baseDate.getFullYear(), baseDate.getMonth(), baseDate.getDate());
  return Math.round((utcTarget - utcBase) / (1000 * 60 * 60 * 24));
}

const now = new Date();
const matchedCases = [];

for (const it of items) {
  const c = it.json;
  if (!c || !c.case_id) continue;

  // Must be in hearing stage and active
  const stage = String(c.legal_proceeding_stage || '').trim().toLowerCase();
  const status = String(c.case_status || '').trim().toLowerCase();
  if (stage !== 'hearing' || status !== 'active') continue;

  const rawHDate = String(c.hearing_date || '').trim();
  if (!rawHDate) continue; // Skip if no hearing date

  let isMatched = false;
  let daysDiff = 0;

  if (manualTargetDate) {
    // If testing for a specific date (e.g. 15/10/2026 or 09/10/2026)
    if (rawHDate === manualTargetDate) {
      isMatched = true;
      daysDiff = reminderDays;
    } else {
      const p1 = parseDate(rawHDate);
      const p2 = parseDate(manualTargetDate);
      if (p1 && p2 && p1.getTime() === p2.getTime()) {
        isMatched = true;
        daysDiff = reminderDays;
      }
    }
  } else {
    // Automated daily cron check: check if difference is reminderDays
    const hDateObj = parseDate(rawHDate);
    if (hDateObj) {
      daysDiff = diffDays(hDateObj, now);
      if (daysDiff === reminderDays) {
        isMatched = true;
      }
    }
  }

  // Filter by case_id if provided in manual input
  if (manualCaseId && c.case_id !== manualCaseId) {
    isMatched = false;
  }

  if (!isMatched) continue;

  // Assemble Clean Lawyer Checklist
  const caseId = c.case_id;
  const clientName = c.client_name || 'Client';
  const clientEmail = c.case_owner_email || 'sahil.soni@trootech.com';
  const clientLocation = c.location || 'Ahmedabad';
  const clientAddress = c.address || 'Ahmedabad';
  const advocateName = c.advocate_name || 'Assigned Counsel';
  const advocateEmail = c.advocate_email || 'sahil.soni@trootech.com';
  const courtName = c.court_name || 'Designated Court Bench';
  const hearingTime = c.hearing_time || '10:30 AM (Standard Sitting)';
  const adverseParty = c.adverse_party || 'None / Not Applicable';
  const docTitle = c.document_title || 'Case Brief & Pleadings';
  const docUrl = c.document_url || '';
  const docDisplay = docUrl ? `<a href="${docUrl}" target="_blank" style="color: #2563eb; text-decoration: underline;">📄 ${docTitle} (Open in Drive)</a>` : `<span>${docTitle} (Pending Vault Upload)</span>`;

  const courtLocation = `${courtName}${clientLocation ? ' (' + clientLocation + ')' : ''}`;

  const lawyerEmailSubject = `[PRE-HEARING ACTION CHECKLIST] Upcoming Court Hearing for Case #${caseId} (${clientName})`;
  const lawyerEmailBody = `
<div style="font-family: Arial, sans-serif; line-height: 1.6; color: #1e293b; max-width: 650px; margin: 0 auto; border: 1px solid #cbd5e1; border-radius: 8px; overflow: hidden;">
  <div style="background-color: #1e3a8a; color: #ffffff; padding: 20px 24px;">
    <h2 style="margin: 0; font-size: 20px; font-weight: 700;">⚖️ Pre-Hearing Action Checklist (Listing in ${reminderDays} Days)</h2>
    <p style="margin: 6px 0 0 0; opacity: 0.9; font-size: 14px;">Case Reference: <strong>#${caseId}</strong> | ${clientName}</p>
  </div>
  <div style="padding: 24px;">
    <p>Dear <strong>Adv. ${advocateName}</strong>,</p>
    <p>This matter is scheduled for hearing before the bench in <strong>${reminderDays} days</strong> (${rawHDate}). Please review the pre-hearing briefing details below:</p>

    <div style="background-color: #f8fafc; border-left: 4px solid #1e3a8a; padding: 16px; margin: 18px 0; border-radius: 4px;">
      <table border="0" cellpadding="6" style="width: 100%; border-collapse: collapse; font-size: 14px;">
        <tr><td style="width: 35%; color: #64748b;"><strong>1. Court Name:</strong></td><td><strong style="color: #0f172a;">🏛️ ${courtName}</strong></td></tr>
        <tr><td style="color: #64748b;"><strong>2. Hearing Time:</strong></td><td><strong style="color: #1e3a8a;">⏰ ${hearingTime}</strong></td></tr>
        <tr><td style="color: #64748b;"><strong>3. Legal Stage:</strong></td><td><span style="background: #e0f2fe; color: #0369a1; padding: 2px 8px; border-radius: 4px; font-weight: bold;">${c.legal_proceeding_stage}</span></td></tr>
        <tr><td style="color: #64748b;"><strong>4. Document Vault:</strong></td><td>${docDisplay}</td></tr>
        <tr><td style="color: #64748b;"><strong>5. Client Details:</strong></td><td><strong style="color: #0f172a;">${clientName}</strong></td></tr>
        <tr><td style="color: #64748b;"><strong>6. Adverse Party Name:</strong></td><td><strong style="color: #b91c1c;">⚠️ ${adverseParty}</strong></td></tr>
        <tr><td style="color: #64748b;"><strong>7. Client Contact Info:</strong></td><td>Email: <a href="mailto:${clientEmail}">${clientEmail}</a><br/>Location: ${clientLocation}<br/>Address: ${clientAddress}</td></tr>
      </table>
    </div>

    <div style="background-color: #f1f5f9; padding: 14px 18px; border-radius: 6px; margin-top: 18px;">
      <strong style="color: #334155;">Litigation Action Items:</strong>
      <ul style="margin: 8px 0 0 0; padding-left: 20px; color: #475569; font-size: 13px;">
        <li>Verify Cause List & Courtroom/Bench assignment for ${rawHDate}.</li>
        <li>Inspect physical document brief and confirm Vakalatnama on record.</li>
        <li>Conduct pre-hearing briefing call with client (${clientName}).</li>
      </ul>
    </div>

    <hr style="border: 0; border-top: 1px solid #e2e8f0; margin: 20px 0;"/>
    <p style="font-size: 12px; color: #64748b; margin: 0; text-align: center;">Legal Practice Management System &bull; Privileged & Confidential Litigation Brief</p>
  </div>
</div>
`.trim();

  const clientEmailSubject = `Upcoming Court Hearing Notice — Case #${caseId} (${clientName})`;
  const clientEmailBody = `
<div style="font-family: Arial, sans-serif; line-height: 1.6; color: #1e293b; max-width: 600px; margin: 0 auto; border: 1px solid #cbd5e1; border-radius: 8px; overflow: hidden;">
  <div style="background-color: #0284c7; color: #ffffff; padding: 20px 24px;">
    <h2 style="margin: 0; font-size: 20px; font-weight: 700;">📅 Upcoming Court Hearing Reminder</h2>
    <p style="margin: 6px 0 0 0; opacity: 0.9; font-size: 14px;">Case Reference: <strong>#${caseId}</strong></p>
  </div>
  <div style="padding: 24px;">
    <p>Dear <strong>${clientName}</strong>,</p>
    <p>This is a courtesy reminder that your legal matter has an upcoming court hearing listed in <strong>${reminderDays} days</strong>:</p>

    <div style="background-color: #f0f9ff; border-left: 4px solid #0284c7; padding: 16px; margin: 18px 0; border-radius: 4px;">
      <table border="0" cellpadding="6" style="width: 100%; border-collapse: collapse; font-size: 14px;">
        <tr><td style="width: 35%; color: #64748b;"><strong>1. Court Date:</strong></td><td><strong style="color: #0284c7; font-size: 15px;">📅 ${rawHDate}</strong></td></tr>
        <tr><td style="color: #64748b;"><strong>2. Hearing Time:</strong></td><td><strong style="color: #0284c7; font-size: 15px;">⏰ ${hearingTime}</strong></td></tr>
        <tr><td style="color: #64748b;"><strong>3. Location:</strong></td><td><strong style="color: #0f172a;">📍 ${courtLocation}</strong></td></tr>
        <tr><td style="color: #64748b;"><strong>4. Assigned Advocate:</strong></td><td><strong style="color: #0f172a;">Adv. ${advocateName}</strong><br/><span style="color: #64748b; font-size: 13px;">Email: ${advocateEmail}</span></td></tr>
      </table>
    </div>

    <p style="font-size: 14px; color: #475569;">Your assigned advocate is actively preparing your case brief and records. If your attendance is required or if our team needs any additional details, your counsel will contact you directly.</p>

    <hr style="border: 0; border-top: 1px solid #e2e8f0; margin: 20px 0;"/>
    <p style="font-size: 12px; color: #94a3b8; margin: 0; text-align: center;">Legal Practice Management System &bull; Privileged & Confidential Notice</p>
  </div>
</div>
`.trim();

  matchedCases.push({
    json: {
      case_id: caseId,
      client_name: clientName,
      client_email: clientEmail,
      client_location: clientLocation,
      client_address: clientAddress,
      advocate_name: advocateName,
      advocate_email: advocateEmail,
      court_name: courtName,
      hearing_date: rawHDate,
      hearing_time: hearingTime,
      legal_proceeding_stage: c.legal_proceeding_stage,
      adverse_party: adverseParty,
      document_title: docTitle,
      document_url: docUrl,
      lawyer_email_subject: lawyerEmailSubject,
      lawyer_email_body: lawyerEmailBody,
      client_email_subject: clientEmailSubject,
      client_email_body: clientEmailBody,
      matched_at: now.toISOString()
    }
  });
}

return matchedCases;
